-- Payroll: 法定調書・退職 (docs/design/22-payroll.md §12).
-- Generated by `prisma migrate diff --from-schema-datamodel <previous schema> --to-schema-datamodel
-- prisma/schema.prisma --script`, then extended by hand with a CHECK constraint (Prisma leaves CHECK
-- constraints alone when it diffs the schema). Both columns are nullable: existing rows stay as
-- they are (在職 / 個人か法人か未確認).

-- AlterTable
ALTER TABLE "partner" ADD COLUMN     "is_individual" BOOLEAN;

-- AlterTable
ALTER TABLE "employee" ADD COLUMN     "left_on" DATE;

-- CHECK constraints
-- 退職日 is after the birth date (a typo of the year would otherwise end the premiums at once).
ALTER TABLE "employee"
  ADD CONSTRAINT "employee_left_on_after_birth" CHECK ("left_on" IS NULL OR "left_on" > "birth_date");
